function Private.Falcon(layout)
  local addonName = 'Falcon'
  local FalconAPI = FalconPublicAPI

  if not E:IsAddOnEnabled(addonName) or not IsAddOnLoaded(addonName) or not FalconAPI or not FalconAPI.Import then
    Private:Print(string.format(L['%s is not available. Please enable it and reload your UI.'], addonName))
    return
  end

  local importString, profileName

  if Private.GetProfileResolution() == 'QUAD_HD' then
    if layout == 'DPS/Tank' then
      importString =
        ''
      profileName = Private.GetLayoutProfileName('DPS/Tank')
    else
      importString =
        ''
      profileName = Private.GetLayoutProfileName('Healer')
    end
  elseif Private.GetProfileResolution() == 'FULL_HD' then
    if layout == 'DPS/Tank' then
      importString =
        ''
      profileName = Private.GetLayoutProfileName('DPS/Tank')
    else
      importString =
        ''
      profileName = Private.GetLayoutProfileName('Healer')
    end
  end

  -- /run print(FalconPublicAPI:Export("FalconGlobalSettings"))
  local success, errorMsg = pcall(function()
    FalconAPI:Import(importString, profileName)
  end)

  if success then
    Private:Print(string.format(L['%s profiles installed.'], addonName))
    Private:PluginInstallStepComplete(addonName)
  else
    Private:Print(string.format(L['%s import failed: %s'], addonName, tostring(errorMsg)))
  end
end
